            /** Format: uuid */
            spaceId: string;
            /** Format: uuid */
            objectId: string | null;
            /** @description The owner's AccountId32 */
            owner: string;
            /** @description Sealed with one of the space's key epochs */
            encryptedName: string;
            spaceKeyEpoch: number;
            keyEpoch: number | null;
            /** @enum {string} */
            scope: "read" | "read_write";
